def hash_password(plain: str) -> str:
    """Hash a plain-text password using bcrypt."""
    return pwd_ctx.hash(plain)

def verify_password(plain: str, hashed: str) -> bool:
    """Check if a plain password matches its stored bcrypt hash."""
    return pwd_ctx.verify(plain, hashed)

def create_access_token(data: dict) -> str:
    """
    Create a signed JWT token.

    HOW IT WORKS:
    - We take a dict (payload) and add an expiry time
    - jose signs it with our SECRET_KEY using HMAC-SHA256
    - The result is a string like: xxxxx.yyyyy.zzzzz
    - Anyone can decode the first two parts (they're base64)
    - But the third part (signature) can only be verified by
      someone who knows the SECRET_KEY
    """
    payload = data.copy()
    expire  = datetime.now(timezone.utc) + timedelta(hours=TOKEN_EXPIRE_HOURS)
    payload.update({"exp": expire})
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)

def decode_token(token: str) -> dict:
    """Verify and decode a JWT. Raises an error if invalid or expired."""
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    except JWTError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid or expired token",
            headers={"WWW-Authenticate": "Bearer"},
        )

def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)):
    """
    Dependency function — extracts and validates the JWT from the
    Authorization header on any protected route.

    USAGE: Add `user = Depends(get_current_user)` to any route
    that requires authentication. FastAPI runs this automatically.
    """
    return decode_token(credentials.credentials)

def require_admin(user: dict = Depends(get_current_user)):
    """Dependency that additionally enforces the admin role."""
    if user.get("role") != "admin":
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Administrator access required"
        )
    return user

def require_scanner(credentials: HTTPAuthorizationCredentials = Depends(security)):
    """
    Dependency for the scanner endpoint.
    The physical scanner authenticates with a static API key stored
    in the .env file rather than a user JWT. This keeps the scanner
    simple — it never needs to log in, it just sends its key.

    WHY a separate key? The scanner is a hardware device. It can't
    do a login flow. We give it one long-lived secret instead.
    Add SCANNER_KEY=your-scanner-secret to your .env file.
    """
    expected = os.getenv("SCANNER_KEY", "")
    if not expected:
        raise HTTPException(status_code=500, detail="SCANNER_KEY not configured")
    if credentials.credentials != expected:
        raise HTTPException(status_code=401, detail="Invalid scanner key")
    return True

def serialize(doc: dict) -> dict:
    """
    Convert MongoDB ObjectId fields to plain strings so they can
    be returned as JSON. FastAPI can't serialize ObjectId natively.
    We also convert any nested ObjectIds if present.
    """
    doc["_id"] = str(doc["_id"])
    return doc


