# ── POST /auth/register ──
# Guests call this to create a new account.
# Account starts as pending=True until an admin approves it.
@app.post("/auth/register", status_code=201)
def register(req: RegisterRequest):
    # Check username isn't already taken
    if db["users"].find_one({"username": req.username}):
        raise HTTPException(status_code=409, detail="Username already exists")

    # Check email isn't already registered
    if db["users"].find_one({"email": req.email}):
        raise HTTPException(status_code=409, detail="Email already registered")

    # Build the user document to store in MongoDB
    user_doc = {
        "username":     req.username,
        "email":        req.email,
        "display_name": req.display_name,
        "password":     hash_password(req.password),  # NEVER store plain text
        "role":         "guest",
        "approved":     False,   # Must be approved by admin before login
        "created_at":   datetime.now(timezone.utc),
    }

    db["users"].insert_one(user_doc)
    return {"message": "Account created. Please wait for admin approval."}


# ── POST /auth/login ──
# Validates credentials and returns a JWT if successful.
@app.post("/auth/login", response_model=TokenResponse)
def login(req: LoginRequest):
    # Look up the user in MongoDB by username
    user = db["users"].find_one({"username": req.username})

    # WHY do we check password even if user doesn't exist?
    # "Timing attacks" — if we return instantly for unknown users
    # but slowly for wrong passwords, an attacker can enumerate
    # valid usernames. Always do the full check regardless.
    if not user or not verify_password(req.password, user["password"]):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password"
        )

    # Guest accounts must be approved by an admin first
    if user["role"] == "guest" and not user.get("approved", False):
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Your account is pending admin approval"
        )

    # Build the JWT payload — this data is accessible on the frontend
    # and the backend without a DB query (that's the power of JWTs)
    token = create_access_token({
        "sub":      str(user["_id"]),   # "sub" = subject (standard JWT claim)
        "username": user["username"],
        "role":     user["role"],
    })

    return TokenResponse(
        access_token=token,
        role=user["role"],
        username=user["username"]
    )


