# ── POST /admin/news ──
# Admin creates a news post.
@app.post("/admin/news", status_code=201)
def create_news(req: NewsPostRequest, admin: dict = Depends(require_admin)):
    if not req.title.strip():
        raise HTTPException(status_code=400, detail="Title cannot be empty")
    if not req.body.strip():
        raise HTTPException(status_code=400, detail="Body cannot be empty")

    post = {
        "post_id":   str(uuid.uuid4()),   # Stable ID for deletion
        "title":     req.title.strip(),
        "body":      req.body.strip(),
        "author":    admin["username"],
        "posted_at": datetime.now(timezone.utc),
    }
    db["news"].insert_one(post)
    post["_id"] = str(post.pop("_id", ""))
    return post


# ── DELETE /admin/news/{post_id} ──
# Admin deletes a news post by its post_id.
@app.delete("/admin/news/{post_id}")
def delete_news(post_id: str, admin: dict = Depends(require_admin)):
    result = db["news"].delete_one({"post_id": post_id})
    if result.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Post not found")
    return {"message": "Post deleted"}


# ─────────────────────────────────────────────
# DATABASE SETUP HELPER
# Run this once to create an initial admin account:
#   python -c "from main import create_admin; create_admin()"
# ─────────────────────────────────────────────

def create_admin(username="admin", password="changeme123"):
    """
    One-time script to seed an admin user.
    Run from the command line, then change the password immediately.
    """
    if db["users"].find_one({"username": username}):
        print(f"Admin user '{username}' already exists.")
        return
    db["users"].insert_one({
        "username":     username,
        "email":        "admin@delt-arcade.local",
        "display_name": "Administrator",
        "password":     hash_password(password),
        "role":         "admin",
        "approved":     True,
        "created_at":   datetime.now(timezone.utc),
    })
    print(f"Admin user '{username}' created. Password: {password}")
    print("IMPORTANT: Change this password immediately after first login!")
